const envelope=JSON.parse(JSON.stringify($json));
const v=envelope.intelligence?.vehicle??{};
const lead=envelope.context?.lead??{};
const present=value=>value!==null&&value!==undefined&&(typeof value!=='string'||value.trim()!=='');
const source=key=>present(v[key])?v[key]:lead[key];
const clean=value=>String(value??'').trim().replace(/\s+/g,' ');
const esc=value=>String(value??'').split('').map(char=>'^$.*+?()[]{}|\\'.includes(char)?'\\'+char:char).join('');
const pattern=value=>esc(value).split(' ').join('\\s+');
const anchored=value=>'^\\s*'+pattern(value)+'\\s*'+String.fromCharCode(36);
const vin=clean(source('vin')).toUpperCase();
const make=clean(source('make'));
const model=clean(source('model'));
const year=clean(source('year'));
const category=envelope.intelligence?.inquiry?.category??'';
const hasVehicleKey=!!(vin||make||model||year);
const alwaysInventory=new Set(['Availability Inquiry','Price Inquiry','Test Drive Request']);
const vehicleBound=new Set(['Closing','Negotiation','Delivery / Pickup','Hidden Price Concern','General Inquiry']);
const required=alwaysInventory.has(category)||(hasVehicleKey&&vehicleBound.has(category));
const dealerId=envelope.identity?.dealer_id||'__UNRESOLVED__';
// Vehicle schema and ingestion use dealerId (camelCase); every inventory query remains tenant-scoped.
const exactCriteria={dealerId:dealerId};
if(vin)exactCriteria.vin={'$regex':anchored(vin),'$options':'i'};
if(year){const numericYear=/^\d{4}$/.test(year)?Number(year):null;exactCriteria.year=numericYear===null?year:{'$in':[numericYear,year]};}
if(make)exactCriteria.make={'$regex':anchored(make),'$options':'i'};
if(model)exactCriteria.model={'$regex':anchored(model),'$options':'i'};
if(!hasVehicleKey)exactCriteria._id='__NO_EXACT_CRITERIA__';
const alternativeCriteria={dealerId:dealerId};
if(!vin&&year&&(make||model)){
  if(make)alternativeCriteria.make={'$regex':anchored(make),'$options':'i'};
  if(model)alternativeCriteria.model={'$regex':anchored(model),'$options':'i'};
}else alternativeCriteria._id='__NO_ALTERNATIVE_CRITERIA__';
envelope.inventory={status:'UNKNOWN',required,request:{vin:vin||null,make:make||null,model:model||null,year:year||null},exact_vehicle:null,exact_match_count:0,exact_matches:[],alternative_count:0,alternatives:[],authoritative_availability:false,warnings:[]};
return [{json:{envelope,required,vin_query:JSON.stringify(exactCriteria),model_query:JSON.stringify(alternativeCriteria)}}];

const base=JSON.parse(JSON.stringify($node['Build Safe Inventory Queries'].json.envelope));
const request=base.inventory.request;
const dealerId=String(base.identity.dealer_id??'');
const id=value=>value?.$oid?String(value.$oid):value===undefined||value===null?'':String(value);
const norm=value=>String(value??'').trim().replace(/\s+/g,' ').toLowerCase();
const same=(left,right)=>norm(left)===norm(right);
const owned=vehicle=>id(vehicle.dealerId)===dealerId;
const validRow=vehicle=>vehicle&&Object.keys(vehicle).length&&(vehicle.make||vehicle.model||vehicle.vin||vehicle._id);
const exactCandidates=$items('Find Exact VIN').map(item=>item.json).filter(vehicle=>validRow(vehicle)&&owned(vehicle));
const alternativeCandidates=$input.all().map(item=>item.json).filter(vehicle=>validRow(vehicle)&&owned(vehicle));
const matches=vehicle=>(!request.vin||same(vehicle.vin,request.vin))&&(!request.year||same(vehicle.year,request.year))&&(!request.make||same(vehicle.make,request.make))&&(!request.model||same(vehicle.model,request.model));
const relevant=vehicle=>request.model?same(vehicle.model,request.model)&&(!request.make||same(vehicle.make,request.make)):request.make?same(vehicle.make,request.make):false;
const unique=rows=>{const seen=new Set();return rows.filter(vehicle=>{const key=id(vehicle._id)||[norm(vehicle.vin),norm(vehicle.year),norm(vehicle.make),norm(vehicle.model),norm(vehicle.trim)].join('|');if(seen.has(key))return false;seen.add(key);return true;});};
const order=(left,right)=>Number(right.year??0)-Number(left.year??0)||norm(left.make).localeCompare(norm(right.make))||norm(left.model).localeCompare(norm(right.model))||norm(left.vin).localeCompare(norm(right.vin))||id(left._id).localeCompare(id(right._id));
const exactRows=unique(exactCandidates).filter(matches).sort(order);
const alternativeRows=unique(alternativeCandidates).filter(vehicle=>!matches(vehicle)&&relevant(vehicle)).sort(order);
const availability=vehicle=>{
  if(vehicle.sold===true||vehicle.deleted===true||vehicle.is_deleted===true)return false;
  for(const key of ['available','is_available'])if(typeof vehicle[key]==='boolean')return vehicle[key];
  const state=String(vehicle.availability??vehicle.inventory_status??vehicle.status??vehicle.salestatus??vehicle.saleStatus??vehicle.sale_status??'').trim().toLowerCase();
  if(['sold','unavailable','deleted'].includes(state))return false;
  if(state==='available')return true;
  return null;
};
const exactMatchCount=exactRows.length;
const alternativeCount=alternativeRows.length;
base.inventory.exact_match_count=exactMatchCount;
base.inventory.alternative_count=alternativeCount;
const summary=vehicle=>({vin:vehicle.vin??null,year:vehicle.year??null,make:vehicle.make??null,model:vehicle.model??null,trim:vehicle.trim??null,body:vehicle.body??null,vehicle_type:vehicle.vehicletype??null,vehicle_class:vehicle.vehicleclass??null,new_used:vehicle.newused??vehicle.condition??null,title:vehicle.title??null,engine:vehicle.engine??null,transmission:vehicle.transmission??null,drive:vehicle.drive??null,mileage:vehicle.mileage??null,fuel:vehicle.fuel??null,exterior_color:vehicle.exteriorcolor??null,interior_color:vehicle.interiorcolor??null,seats:vehicle.seats??null,price:vehicle.internetprice??null,vdp_url:vehicle.shortUrl??null,availability:availability(vehicle)});
if(exactRows.length){
  const available=exactRows.filter(vehicle=>availability(vehicle)===true);
  const unknown=exactRows.filter(vehicle=>availability(vehicle)===null);
  const selected=available[0]??unknown[0]??exactRows[0];
  base.inventory.exact_matches=exactRows.slice(0,5).map(summary);
  base.inventory.exact_vehicle=summary(selected);
  if(available.length){base.inventory.status='EXACT_AVAILABLE';base.inventory.authoritative_availability=true;}
  else if(exactRows.every(vehicle=>availability(vehicle)===false)){base.inventory.status='EXACT_UNAVAILABLE';base.inventory.authoritative_availability=true;}
  else{base.inventory.status='UNKNOWN';base.inventory.warnings.push('EXACT_MATCH_AVAILABILITY_UNRESOLVED');}
  if(exactRows.length>1)base.inventory.warnings.push('MULTIPLE_EXACT_INVENTORY_MATCHES');
  base.inventory.alternatives=alternativeRows.slice(0,5).map(summary);
}else if(alternativeRows.length){
  base.inventory.status='ALTERNATIVES';
  base.inventory.alternatives=alternativeRows.slice(0,5).map(summary);
  if(alternativeRows.some(vehicle=>availability(vehicle)===null))base.inventory.warnings.push('ALTERNATIVE_AVAILABILITY_FIELD_UNRESOLVED');
}else{
  base.inventory.status='UNKNOWN';
  base.inventory.warnings.push(request.vin||request.make||request.model||request.year?'NO_INVENTORY_MATCH':'NO_INVENTORY_KEY');
}
return [{json:base}];
